test('more than 100 favorites keep saved state on later pages', async ({ browser }) => {
  const { context, page } = await view(browser, user)
  try {
    for (const job of jobs) expect((await user.put(api + '/me/favorites/' + job.id, { headers: headers(userIdentity) })).status()).toBe(204)
    await page.goto('/favorites?offset=100')
    await expect(page.locator('.job-card')).toHaveCount(6)
    await expect(page.getByRole('button', { name: /^取消收藏 QA-/ })).toHaveCount(6)
    const response = page.waitForResponse(value => value.request().method() === 'DELETE' && value.url().includes('/me/favorites/'))
    await page.getByRole('button', { name: /^取消收藏 QA-/ }).first().click()
    expect((await response).status()).toBe(204)
    await expect(page.locator('.job-card')).toHaveCount(5)
    await expect(page.getByRole('button', { name: /^取消收藏 QA-/ })).toHaveCount(5)
    expect((await (await user.get(api + '/me/favorites?limit=100&offset=100')).json()).items).toHaveLength(5)
  } finally {
    for (const job of jobs) await user.delete(api + '/me/favorites/' + job.id, { headers: headers(userIdentity) })
    await context.close()
  }
})

test('more than 100 applications keep recorded state on the job board', async ({ browser }) => {
  const records: Application[] = []
  const { context, page } = await view(browser, user)
  const stateBatches: number[] = []
  const fullPersonalLists: string[] = []
  page.on('request', request => {
    const url = new URL(request.url())
    if (url.pathname.endsWith('/me/job-states')) stateBatches.push(url.searchParams.getAll('job_id').length)
    if (/\/me\/(favorites|applications)$/.test(url.pathname)) fullPersonalLists.push(url.pathname)
  })
  try {
    for (const job of jobs) records.push(await createRecord(user, userIdentity, job))
    await page.goto('/jobs?status=all&limit=100')
    await expect(page.locator('.job-card')).toHaveCount(100)
    await expect(page.getByRole('button', { name: '查看进度', exact: true })).toHaveCount(100)
    expect(stateBatches).toEqual([100])
    expect(fullPersonalLists).toEqual([])
    const creates: string[] = []
    page.on('request', request => { if (request.method() === 'POST' && request.url().endsWith('/me/applications')) creates.push(request.url()) })
    await page.getByRole('button', { name: '查看进度', exact: true }).first().click()
    await expect(page).toHaveURL(/\/applications$/)
    await expect(page.getByRole('heading', { name: '我的投递进度' })).toBeVisible()
    expect(creates).toEqual([])
  } finally {
    for (const record of records) await removeRecord(user, userIdentity, record.id)
    await context.close()
  }
})

test('page state failures can retry and stale state responses cannot replace the next search', async ({ browser }) => {
  const { context, page } = await view(browser, user)
  let releaseOld = () => {}
  const oldGate = new Promise<void>(resolve => { releaseOld = resolve })
  let oldStarted = () => {}
  const oldRequest = new Promise<void>(resolve => { oldStarted = resolve })
  const first = jobs.find(job => job.title === 'QA-001')!
  try {
    await page.route('**/api/v1/me/job-states?*', route => route.abort())
    await page.goto('/jobs?q=QA-002')
    await expect(page.getByRole('alert')).toContainText('暂时没有加载成功')
    await expect(page.locator('.job-card')).toHaveCount(0)
    await page.unroute('**/api/v1/me/job-states?*')
    await page.getByRole('button', { name: '重新加载', exact: true }).click()
    await expect(page.getByRole('heading', { name: 'QA-002', exact: true })).toBeVisible()
    await page.route('**/api/v1/me/job-states?*', async route => {
      const ids = new URL(route.request().url()).searchParams.getAll('job_id')
      if (ids.includes(first.id)) {
        oldStarted()
        await oldGate
        await route.fulfill({ json: { items: [{ job_id: first.id, favorite: true, recorded: true }] } })
      } else await route.continue()
    })
    await page.getByLabel('岗位关键词').fill('QA-001')
    await page.getByRole('button', { name: '搜索', exact: true }).click()
    await oldRequest
    await page.getByLabel('岗位关键词').fill('QA-002')
    await page.getByRole('button', { name: '搜索', exact: true }).click()
    await expect(page.getByRole('heading', { name: 'QA-002', exact: true })).toBeVisible()
    const completed = page.waitForResponse(response => response.url().includes('/me/job-states?') && new URL(response.url()).searchParams.getAll('job_id').includes(first.id))
    releaseOld()
    await completed
    await page.evaluate(() => new Promise(resolve => requestAnimationFrame(() => requestAnimationFrame(resolve))))
    await expect(page.getByRole('heading', { name: 'QA-002', exact: true })).toBeVisible()
    await expect(page.getByRole('heading', { name: 'QA-001', exact: true })).toHaveCount(0)
    await expect(page.getByRole('button', { name: '收藏 QA-002', exact: true })).toBeVisible()
    await expect(page.getByRole('button', { name: '记录投递', exact: true })).toBeVisible()
  } finally { releaseOld(); await context.close() }
})
